#include <stdio.h>
#define MAXN 16
int parent[MAXN], rk[MAXN];
void init(int n){ for(int i=0;i<n;i++){ parent[i]=i; rk[i]=0; } }
int find(int x){ int r=x; while(parent[r]!=r) r=parent[r];
    while(parent[x]!=r){ int t=parent[x]; parent[x]=r; x=t; } return r; }
void unite(int a,int b){ int ra=find(a),rb=find(b); if(ra==rb) return;
    if(rk[ra]<rk[rb]) parent[ra]=rb; else if(rk[ra]>rk[rb]) parent[rb]=ra;
    else { parent[rb]=ra; rk[ra]++; } }
int main(void){
    int n=8; init(n);
    int edges[][2]={{0,1},{1,2},{3,4},{5,6},{6,7}};
    int E=5;
    for(int i=0;i<E;i++) unite(edges[i][0],edges[i][1]);
    int cnt=0;
    for(int i=0;i<n;i++) if(find(i)==i) cnt++;
    printf("节点数 n = %d，合并边 = %d 条\n", n, E);
    printf("并查集统计连通分量个数 = %d\n", cnt);
    return 0;
}
